'use client';

import { useEffect, useMemo, useState } from 'react';

import {
  DOW,
  MONTHS,
  dateKey,
  fmtDateHuman,
  hourSlots,
  isWithinRange,
  pad,
  todayDateOnly,
} from '@/lib/calendar-helpers';
import type { AvailabilitySlot } from '@/lib/types';
import ReservationModal from './ReservationModal';

export default function CalendarView() {
  const today = useMemo(() => todayDateOnly(), []);
  const [calYear, setCalYear] = useState(today.getFullYear());
  const [calMonth, setCalMonth] = useState(today.getMonth());
  const [selectedDate, setSelectedDate] = useState<string | null>(null);
  const [slots, setSlots] = useState<AvailabilitySlot[]>([]);
  const [loading, setLoading] = useState(true);
  const [modalHour, setModalHour] = useState<number | null>(null);
  const [refreshKey, setRefreshKey] = useState(0);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    fetch(`/api/availability?year=${calYear}&month=${calMonth + 1}`)
      .then((res) => res.json())
      .then((data) => {
        if (!cancelled) setSlots(data.slots || []);
      })
      .catch(() => {
        if (!cancelled) setSlots([]);
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [calYear, calMonth, refreshKey]);

  function slotsOnDate(key: string) {
    return slots.filter((s) => s.date === key);
  }
  function isHourBusy(key: string, hour: number) {
    return slotsOnDate(key).some((s) => hour >= s.start_hour && hour < s.end_hour);
  }
  function dayInfo(key: string) {
    const list = slotsOnDate(key);
    const total = hourSlots().length;
    const busyCount = list.reduce((a, s) => a + (s.end_hour - s.start_hour), 0);
    return { hasBusy: list.length > 0, total, busyCount };
  }

  function changeMonth(delta: number) {
    let m = calMonth + delta;
    let y = calYear;
    if (m < 0) { m = 11; y -= 1; }
    if (m > 11) { m = 0; y += 1; }
    setCalMonth(m);
    setCalYear(y);
    setSelectedDate(null);
  }

  const firstOfMonth = new Date(calYear, calMonth, 1);
  const startDow = (firstOfMonth.getDay() + 6) % 7;
  const daysInMonth = new Date(calYear, calMonth + 1, 0).getDate();
  const monthLabel = `${MONTHS[calMonth]} ${calYear}`;

  const cells: React.ReactNode[] = [];
  for (let i = 0; i < startDow; i++) {
    cells.push(<div key={`empty-${i}`} className="cal-day empty" />);
  }
  for (let d = 1; d <= daysInMonth; d++) {
    const dateObj = new Date(calYear, calMonth, d);
    dateObj.setHours(0, 0, 0, 0);
    const key = dateKey(calYear, calMonth, d);
    const inRange = isWithinRange(dateObj);
    const isToday = dateObj.getTime() === today.getTime();
    const isSelected = key === selectedDate;
    const info = dayInfo(key);

    cells.push(
      <button
        key={key}
        type="button"
        disabled={!inRange}
        onClick={() => setSelectedDate(key)}
        className={[
          'cal-day',
          isToday ? 'today' : '',
          isSelected ? 'selected' : '',
          !inRange ? 'disabled' : '',
        ].join(' ')}
      >
        {info.hasBusy && <span className="ind busy" aria-hidden="true" />}
        <span className="num">{d}</span>
      </button>
    );
  }

  const slotList = selectedDate ? hourSlots() : [];
  const isSelectedToday =
    selectedDate &&
    new Date(selectedDate + 'T00:00:00').getTime() === today.getTime();
  const nowHour = new Date().getHours();

  return (
    <div className="wrap">
      {/* Hlavička se znakem obce */}
      <div className="lede">
        <div style={{ display: 'flex', alignItems: 'center', gap: '14px' }}>
          <img src="data:image/jpeg;base64," alt="Znak obce Čtyřkoly" style={{ width: '52px', height: '62px', objectFit: 'contain' }} />
          <div>
            <h2>Rezervace klubovny</h2>
          </div>
        </div>
        <div className="legend">
          <span><span className="dot free" /> volno</span>
          <span><span className="dot busy" /> obsazeno</span>
        </div>
      </div>

      {/* Info text pod nadpisem */}
      <div className="info-box">
        Rezervace v této aplikaci je jen žádostí, která je platná následným potvrzením ze strany
        obecního úřadu a podepsáním smlouvy o pronájmu. Nájemné činí 100 Kč/hod., maximálně
        300 Kč/den. Zájmové spolky zaměřené na aktivity dětí a mládeže jsou od poplatku
        osvobozeny. Rezervace lze vytvořit nejdříve na dnešní den a nejdéle rok dopředu.
      </div>

      <div className="cal-card">
        <div className="cal-header">
          <div className="cal-month">{monthLabel}</div>
          <div className="cal-nav">
            <button className="btn btn-sm" onClick={() => changeMonth(-1)}>‹ dřívější</button>
            <button className="btn btn-sm" onClick={() => changeMonth(1)}>pozdější ›</button>
          </div>
        </div>
        <div className="cal-grid">
          {DOW.map((d) => (
            <div key={d} className="cal-dow">{d}</div>
          ))}
          {cells}
        </div>
        {loading && <div className="hint" style={{ marginTop: 10 }}>Načítám obsazenost…</div>}
      </div>

      {selectedDate && (
        <div className="slots-card">
          <div className="slots-title">
            <h3>{fmtDateHuman(selectedDate)}</h3>
            <span className="hint">
              {slotsOnDate(selectedDate).length
                ? `${slotsOnDate(selectedDate).length} rezervace tento den`
                : 'zatím žádné rezervace'}
            </span>
          </div>
          <div className="slots-grid">
            {slotList.map((s) => {
              const busy = isHourBusy(selectedDate, s.start);
              const isPast = !!isSelectedToday && s.start <= nowHour;
              let cls = 'slot';
              if (busy) cls += ' busy';
              else if (isPast) cls += ' past';
              return (
                <button
                  key={s.start}
                  type="button"
                  className={cls}
                  disabled={busy || isPast}
                  onClick={() => setModalHour(s.start)}
                >
                  {pad(s.start)}:00–{pad(s.end)}:00
                </button>
              );
            })}
          </div>
        </div>
      )}

      {/* Provozní řád */}
      <div className="provozni-rad">
        <h3>Provozní řád obecní klubovny</h3>
        <p className="provozni-rad-uvod">
          Obec Čtyřkoly vydává tento provozní řád obecní klubovny (dále jen „klubovna"),
          který upravuje podmínky jejího užívání.
        </p>
        <div className="provozni-rad-grid">
          <div className="provozni-rad-item">
            <h4>1. Účel klubovny</h4>
            <p>Klubovna slouží jako prostor pro volnočasové, kulturní a komunitní aktivity obyvatel obce všech věkových kategorií, s důrazem na děti a mládež. Klubovna není určena k provozování pohostinství, barových aktivit ani hlučných večírků.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>2. Oprávnění uživatelé</h4>
            <p>Klubovnu mohou využívat obyvatelé obce, osoby vlastnící nemovitost v obci a případně další osoby pouze se souhlasem obce. Uživatel musí být starší 18 let nebo mít odpovědnou dospělou osobu.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>3. Registrace a přístup</h4>
            <p>Každý uživatel se zapíše na obecním úřadě a potvrdí souhlas s tímto řádem. Obdrží klíč a přístupový kód/čip k EZS.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>4. Rezervace</h4>
            <p>Klubovna je k dispozici pravidelným i jednorázovým uživatelům. Termíny je nutné rezervovat předem. Obec si vyhrazuje právo rezervaci změnit nebo zrušit.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>5. Poplatky</h4>
            <p>Užívání klubovny je zpoplatněno. Nájemné činí 100 Kč/hod., max. 300 Kč/den. Zájmové spolky zaměřené na děti a mládež jsou od poplatku osvobozeny.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>6. Povinnosti uživatele</h4>
            <p>Uživatel je povinen udržovat pořádek, po skončení prostor uklidit, odnést odpad, uvést vše do původního stavu, dodržovat noční klid (22:00–6:00) a chovat se ohleduplně.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>7. Zákazy</h4>
            <p>V klubovně je zakázána nadměrná konzumace alkoholu a užívání návykových látek. Konzumace alkoholu a návykových látek je zakázána mladistvým. V klubovně a zastřešených prostorách je zakázáno kouření. Dále je zakázáno pořádat hlučné večírky,ničit vybavení a rušit veřejný pořádek. Je též zakázáno jakkoliv manipulovat/přenastavovat zařízení v technické místnosti.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>8. Odpovědnost</h4>
            <p>Uživatel odpovídá za všechny osoby, které do klubovny vpustí, a za veškeré škody vzniklé během užívání. Zavazuje se škody uhradit v plné výši.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>9. Zabezpečení</h4>
            <p>Při odchodu je uživatel povinen zavřít okna, zhasnout, vypnout elektrické spotřebiče, uzamknout objekt a aktivovat EZS.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>10. Sankce</h4>
            <p>Porušení tohoto řádu může vést k odebrání přístupu ke klubovně a k povinnosti uhradit vzniklou škodu.</p>
          </div>
          <div className="provozni-rad-item">
            <h4>11. Závěrečná ustanovení</h4>
            <p>Tento provozní řád je závazný pro všechny uživatele klubovny.</p>
          </div>
        </div>
      </div>

      {selectedDate && modalHour !== null && (
        <ReservationModal
          dateKeyStr={selectedDate}
          initialHour={modalHour}
          existingSlots={slotsOnDate(selectedDate)}
          onClose={() => setModalHour(null)}
          onCreated={() => {
            setModalHour(null);
            setRefreshKey((k) => k + 1);
          }}
        />
      )}
    </div>
  );
}
